insert into faqs select * from jsonb_populate_record(null::faqs, '{"id": "f5fb9e53-ee7c-456f-b308-915f96fb2085", "scope": "visa", "answer": "The total shown on this page includes the government fee and the Atlys processing fee. There are no hidden charges, and every fee change is published in our fee change audit.", "category": "General Information", "question": "How much does the {country} visa cost?", "sort_order": 2, "destination_id": null}'::jsonb) on conflict do nothing;
insert into faqs select * from jsonb_populate_record(null::faqs, '{"id": "390512c0-a78e-41a0-b0d3-e92ba5c7dbf8", "scope": "visa", "answer": "The required documents are listed on this page. Most applicants only need a passport valid for at least 6 months and a recent photo. Atlys checks every document before it is submitted.", "category": "Eligibility & Requirements", "question": "Which documents do I need for a {country} visa?", "sort_order": 3, "destination_id": null}'::jsonb) on conflict do nothing;
insert into faqs select * from jsonb_populate_record(null::faqs, '{"id": "4b8711f8-7707-4275-b8fa-1bf8c393c6ec", "scope": "visa", "answer": "Your passport should be valid for at least 6 months from your date of arrival in {country} and have at least two blank pages.", "category": "Eligibility & Requirements", "question": "How long must my passport be valid?", "sort_order": 4, "destination_id": null}'::jsonb) on conflict do nothing;
insert into faqs select * from jsonb_populate_record(null::faqs, '{"id": "c78b083f-2039-4f1d-b068-c220b63fa45f", "scope": "visa", "answer": "Yes. Add every traveller to a single application. You upload once, pay once, and get one guaranteed date for the whole group.", "category": "Eligibility & Requirements", "question": "Can I apply for my family in one application?", "sort_order": 5, "destination_id": null}'::jsonb) on conflict do nothing;
insert into faqs select * from jsonb_populate_record(null::faqs, '{"id": "419b6441-08b1-48b9-a578-dc89e01eb6b2", "scope": "visa", "answer": "Pick your departure date, add travellers, upload the passport and photo, review, and pay. Atlys fills the government forms, checks your documents and submits the application for you.", "category": "Application Process", "question": "How do I apply for a {country} visa online?", "sort_order": 6, "destination_id": null}'::jsonb) on conflict do nothing;
insert into faqs select * from jsonb_populate_record(null::faqs, '{"id": "5ec9a3ca-e40a-48c4-87bc-a4c5c123348e", "scope": "visa", "answer": "Apply as soon as your travel dates are fixed. The guaranteed date is shown before you pay, so you can make sure your visa arrives before you fly.", "category": "Application Process", "question": "How early should I apply?", "sort_order": 7, "destination_id": null}'::jsonb) on conflict do nothing;
insert into faqs select * from jsonb_populate_record(null::faqs, '{"id": "9bb551e2-6d23-48e0-b663-95553b5c5a83", "scope": "visa", "answer": "Sign in and open your application. Every step, from document checks to government processing, is shown live with a timestamp.", "category": "Status Tracking", "question": "How can I track my {country} visa application?", "sort_order": 8, "destination_id": null}'::jsonb) on conflict do nothing;
