insert into faqs select * from jsonb_populate_record(null::faqs, '{"id": "d427afe4-eda9-4e2e-a7a9-54cc4c90fec9", "scope": "visa", "answer": "If your visa arrives after the guaranteed date, the Atlys service fee is refunded in full. That is the On Time Guarantee.", "category": "Refunds, Rejections & Reapplications", "question": "What happens if my {country} visa is late?", "sort_order": 10, "destination_id": null}'::jsonb) on conflict do nothing;
insert into faqs select * from jsonb_populate_record(null::faqs, '{"id": "18594dfe-9197-47fa-813e-4cc47a2e671d", "scope": "visa", "answer": "We build a free re-application strategy with you. If the route is covered and the visa is rejected again, you get every pound back.", "category": "Refunds, Rejections & Reapplications", "question": "What if my {country} visa is rejected?", "sort_order": 11, "destination_id": null}'::jsonb) on conflict do nothing;
insert into faqs select * from jsonb_populate_record(null::faqs, '{"id": "058550af-73f4-4416-b1ad-3da13da92768", "scope": "visa", "answer": "Extensions depend on the immigration rules of {country}. Contact support before your visa expires and our experts will guide you through the options.", "category": "Visa Extension & Overstays", "question": "Can I extend my {country} visa?", "sort_order": 12, "destination_id": null}'::jsonb) on conflict do nothing;
